(async () => {
  const results = {};

  // 获取 loginForm 可见性
  const loginForm = document.getElementById('loginForm');
  results.loginFormVisible = loginForm ? loginForm.style.display !== 'none' : false;

  // 获取 userInfo 可见性
  const userInfo = document.getElementById('userInfo');
  results.userInfoVisible = userInfo ? userInfo.classList.contains('show') : false;

  // 获取登录邮箱
  const userEmail = document.getElementById('userEmail');
  results.userEmail = userEmail ? userEmail.textContent : null;

  // 获取容器坐标
  const container = document.querySelector('.login-container');
  if (container) {
    const rect = container.getBoundingClientRect();
    results.containerRect = {
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: rect.height,
      top: rect.top,
      right: rect.right,
      bottom: rect.bottom,
      left: rect.left
    };
  }

  // 获取 innerWidth 和 scrollWidth
  results.innerWidth = window.innerWidth;
  results.scrollWidth = document.documentElement.scrollWidth;

  // 获取 localStorage
  const storageKey = 'macbot_e2e_s2_parallel_fc45ecd3b62c_login';
  results.localStorage = localStorage.getItem(storageKey);

  return results;
})()

